    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const addResult = addLine(result.value, { sku: 'DEV-HOUR', qty: 10 });
  assert.equal(addResult.ok, true);
  assert.equal(addResult.value.lines[1].discountPercent, 0);
});

test('addLine rejects invalid discountPercent', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: 150 }), { ok: false, error: 'DISCOUNT_INVALID' });
  assert.deepEqual(addLine(result.value, { sku: 'DEV-HOUR', qty: 10, discountPercent: -5 }), { ok: false, error: 'DISCOUNT_INVALID' });
});
